import{_ as t,o as a,c as s,ag as o}from"./chunks/framework.CvgP6Fyv.js";const u=JSON.parse('{"title":"Core Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"guides/concepts.md","filePath":"guides/concepts.md"}'),r={name:"guides/concepts.md"};function n(i,e,d,c,l,h){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h1><h2 id="streams" tabindex="-1">Streams <a class="header-anchor" href="#streams" aria-label="Permalink to &quot;Streams&quot;">​</a></h2><p>Dendrite acquires data over <a href="https://labstreaminglayer.org" target="_blank" rel="noreferrer">LSL</a> (Lab Streaming Layer). Any LSL-compatible amplifier or software outlet can be used. Each stream has a type (EEG, EMG, EOG, Events), channel count, and sample rate. Multiple streams can be active simultaneously and are recorded together into a single session.</p><p>For development without hardware, the <a href="./stream-replay.html">Stream Manager</a> can replay recorded files or public datasets as live LSL streams.</p><h2 id="sessions-and-recordings" tabindex="-1">Sessions and Recordings <a class="header-anchor" href="#sessions-and-recordings" aria-label="Permalink to &quot;Sessions and Recordings&quot;">​</a></h2><p>A <strong>session</strong> starts when you click Start and ends when you click Stop. During a session, all incoming stream data is saved continuously to an HDF5 file alongside event markers and metadata. Each recording is stored under a study and tagged with subject, session, and run identifiers following BIDS-inspired naming.</p><h2 id="modes" tabindex="-1">Modes <a class="header-anchor" href="#modes" aria-label="Permalink to &quot;Modes&quot;">​</a></h2><p>Modes are the processing units that run during a session. Each mode is a separate process that reads from the shared data buffers, applies its logic, and outputs results. You can run multiple mode instances simultaneously.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Purpose</th><th style="text-align:center;">Requires decoder</th></tr></thead><tbody><tr><td><strong><a href="./synchronous-mode.html">Synchronous</a></strong></td><td>Segments data around events into epochs, requests decoder training, tracks prequential accuracy</td><td style="text-align:center;">No (requests training from ML service)</td></tr><tr><td><strong><a href="./asynchronous-mode.html">Asynchronous</a></strong></td><td>Continuous sliding-window classification with dwell-based detection</td><td style="text-align:center;">Yes</td></tr><tr><td><strong><a href="./neurofeedback-mode.html">Neurofeedback</a></strong></td><td>Real-time band power extraction via Welch&#39;s method</td><td style="text-align:center;">No</td></tr></tbody></table><p>Modes are composable: a synchronous mode can train a decoder that an asynchronous mode uses in the same session (<code>decoder_source: &quot;online&quot;</code>).</p><h2 id="decoders" tabindex="-1">Decoders <a class="header-anchor" href="#decoders" aria-label="Permalink to &quot;Decoders&quot;">​</a></h2><p>A <strong>decoder</strong> is a trained classifier that maps preprocessed EEG (or other signal) epochs to class labels. Decoders wrap either neural networks (EEGNet, etc.) or classical pipelines (CSP+LDA) behind a unified sklearn-compatible interface.</p><p>Decoders can be trained in two ways:</p><ul><li><strong>Online</strong> — a synchronous mode requests training from the ML service as epochs accumulate during a live session</li><li><strong>Offline</strong> — the ML Workbench loads recordings or public datasets and trains in the background</li></ul><p>A saved decoder is a JSON config (input shape, class mapping, model type) paired with a model file (<code>.pt</code> for neural, <code>.joblib</code> for classical).</p><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><p>Events are timestamped markers sent over LSL during a session — typically from a task application. Each event has a numeric <code>event_id</code> and a string <code>event_type</code>. Events drive epoch segmentation in synchronous mode and provide ground truth for asynchronous mode metrics. See <a href="./send-events.html">Send Events</a>.</p><h2 id="output-protocols" tabindex="-1">Output Protocols <a class="header-anchor" href="#output-protocols" aria-label="Permalink to &quot;Output Protocols&quot;">​</a></h2><p>Mode outputs (predictions, band powers) can be forwarded to external applications over LSL, TCP socket, ZMQ, or ROS2. This lets task applications close the loop — receiving classifications and adapting the paradigm in real time. See <a href="./../architecture/task-application-layer.html">Task Application Layer</a>.</p>',19)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
